const bookings = $input.all().map((i) => i.json).filter((b) => b && b.uid);

if (bookings.length === 0) {
  return [{ json: { subject: 'No bookings via Carly this week', html: '<p>No bookings scheduled for the week ahead.</p>' } }];
}

bookings.sort((a, b) => new Date(a.start_time) - new Date(b.start_time));

const fmt = (iso) =>
  new Date(iso).toLocaleString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });

const rows = bookings
  .map((b) => {
    const a = (b.attendees && b.attendees[0]) || {};
    const who = a.name ? `${a.name}${a.email ? ` (${a.email})` : ''}` : '-';
    const cell = 'padding:6px 12px;border-bottom:1px solid #eee';
    return `<tr><td style="${cell}">${fmt(b.start_time)}</td><td style="${cell}">${b.title || ''}</td><td style="${cell}">${who}</td><td style="${cell}">${b.status}</td></tr>`;
  })
  .join('');

const th = 'text-align:left;padding:6px 12px;border-bottom:2px solid #ddd';
const html = `<div style="font-family:sans-serif;font-size:14px;color:#222"><h2>Your bookings via Carly this week (${bookings.length})</h2><table style="border-collapse:collapse"><tr><th style="${th}">When</th><th style="${th}">Event</th><th style="${th}">Who</th><th style="${th}">Status</th></tr>${rows}</table></div>`;

return [{ json: { subject: `${bookings.length} booking(s) via Carly this week`, html } }];
